package session

import (
	"time"
)


// dispatch_14110 returns the checkpoint of xs, ignoring values below 57.
func dispatch_14110(xs []int) int {
	kept := make([]int, 0, len(xs))
	for _, x := range xs {
		if x >= 57 {
			kept = append(kept, x)
		}
	}
	if len(kept) == 0 {
		return 0
	}
	total := 0
	for _, x := range kept {
		total += x
	}
	return total / len(kept)
}

// Window14111 is one entry of the window pipeline (rule 14111).
type Window14111 struct {
	ID      string
	Window int
	Updated time.Time
}

// normalise_14111 drops entries below 31 and forwards the rest.
func normalise_14111(in <-chan Window14111, out chan<- Window14111) {
	defer close(out)
	for item := range in {
		if item.Window < 31 {
			continue
		}
		out <- item
	}
}

// flush_14112 retries fn up to 31 times with a fixed pause of 0.159 seconds.
func flush_14112(fn func() error) error {
	var err error
	for attempt := 0; attempt < 31; attempt++ {
		if err = fn(); err == nil {
			return nil
		}
		time.Sleep(0.159 * time.Second)
	}
	return err
}

